  'plans.faqWhatIsPlusAnswer': 'Είναι το premium πλάνο του Chatyy που προστατεύει όλες τις συνομιλίες, φωτογραφίες και βίντεο σου. Με το Chatyy One, ακόμα και αν διαγράψεις κάτι κατά λάθος, μπορείς να το ανακτήσεις σε έως 30 ημέρες. Επιπλέον, κερδίζεις 200GB αποθηκευτικού χώρου, One AI ως προσωπικό βοηθό, και μπορείς να στείλεις αρχεία έως 100MB.',
  'plans.faqCancelAnswer': 'Η συνδρομή σου παραμένει ενεργή μέχρι το τέλος της πληρωμένης περιόδου. Μετά από αυτό, επιστρέφεις στο δωρεάν πλάνο. Οι φωτογραφίες και τα βίντεο που υπερβαίνουν τα 15GB θα διατηρηθούν για 30 ημέρες για να κάνεις λήψη.',
  'plans.faqHowFamily': 'Πώς λειτουργεί το πλάνο Pro;',
  'plans.faqHowFamilyAnswer': 'Μπορείς να προσθέσεις έως 4 άτομα από την οικογένειά σου. Όλοι μοιράζονται 500GB αποθηκευτικού χώρου και απολαμβάνουν όλα τα οφέλη του Chatyy One. Κάθε άτομο έχει τον ιδιωτικό του χώρο — κανείς δεν βλέπει τα αρχεία των άλλων.',
  'plans.faqChangePlanAnswer': 'Ναι! Αν κάνεις αναβάθμιση από Plus σε Pro, θα χρεωθείς μόνο τη διαφορά. Αν κάνεις υποβάθμιση, το τρέχον πλάνο παραμένει μέχρι το τέλος της περιόδου.',
  'plans.faqCardDeclined': 'Η κάρτα μου απορρίφθηκε, τι να κάνω;',
  'plans.faqCardDeclinedAnswer': 'Έχεις 7 ημέρες για να ενημερώσεις την κάρτα σου. Κατά τη διάρκεια αυτής της περιόδου, όλα τα οφέλη σου συνεχίζουν να λειτουργούν. Μετά από 7 ημέρες, το πλάνο επιστρέφει στο δωρεάν.',
  'plans.faqDataSafe': 'Τα δεδομένα μου είναι ασφαλή;',
  'plans.faqDataSafeAnswer': 'Ναι! Τα δεδομένα πληρωμής σου επεξεργάζονται με κρυπτογράφηση από άκρη σε άκρη. Δεν αποθηκεύουμε τον αριθμό της κάρτας σου — μόνο τα τελευταία 4 ψηφία για αναφορά.',
